import math

SR = 22_050
N_MELS = 80
HOP = 256
WIN = 1024

MEL_KEYS = ("sample_rate", "n_mels", "hop", "win", "fmin", "fmax")


def frame_seconds(sample_rate=SR, hop=HOP):
    return hop / sample_rate


def frames_for_seconds(seconds, sample_rate=SR, hop=HOP):
    return int(round(seconds / frame_seconds(sample_rate, hop)))


def mel_shape(seconds, n_mels=N_MELS, sample_rate=SR, hop=HOP):
    return (n_mels, frames_for_seconds(seconds, sample_rate, hop))


def alignment(t_in, t_out, sigma=0.7):
    rows = []
    for step in range(t_out):
        centre = 0.0 if t_out == 1 else step * (t_in - 1) / (t_out - 1)
        row = [math.exp(-0.5 * ((index - centre) / sigma) ** 2)
               for index in range(t_in)]
        total = sum(row)
        rows.append([value / total for value in row])
    return rows


def peaks(align):
    return [max(range(len(row)), key=lambda index: row[index]) for row in align]


def is_monotonic(align):
    found = peaks(align)
    return all(b >= a for a, b in zip(found, found[1:]))


def coverage(align):
    if not align:
        return 0.0
    return len(set(peaks(align))) / len(align[0])


def context_vectors(align, encoder_states):
    width = len(encoder_states[0])
    out = []
    for row in align:
        vector = [0.0] * width
        for weight, state in zip(row, encoder_states):
            for index in range(width):
                vector[index] += weight * state[index]
        out.append(vector)
    return out


def decode_length(stop_logits, threshold=0.5, max_steps=None):
    limit = len(stop_logits) if max_steps is None else min(max_steps,
                                                           len(stop_logits))
    for step in range(limit):
        if 1 / (1 + math.exp(-stop_logits[step])) > threshold:
            return step
    return limit


def assert_compatible(acoustic, vocoder):
    for key in MEL_KEYS:
        if acoustic.get(key) != vocoder.get(key):
            raise ValueError(
                f"mel configuration differs on {key!r}: "
                f"{acoustic.get(key)!r} vs {vocoder.get(key)!r}")
    return True
